// ARCN1 binary format definitions. Pure encoding/decoding helpers — no
// crypto operations live here, only the byte layout.

export const ARCN1_MAGIC = Buffer.from('ARCN1\0\0\0', 'binary');
export const ARCN1_HEADER_SIZE = 40;
export const ARCN1_TRAILER_SIZE = 32;
export const ARCN1_CHUNK_PLAINTEXT_SIZE = 64 * 1024; // 64KB

export enum AlgorithmId {
  AES_256_GCM_64KB = 0x01,
}

export interface ArcnHeader {
  version: number;
  algorithm: AlgorithmId;
  iv: Buffer;
  tag: Buffer;
}

export function encodeHeader(h: ArcnHeader): Buffer {
  if (h.iv.length !== 12) throw new Error('iv must be 12 bytes');
  if (h.tag.length !== 16) throw new Error('tag must be 16 bytes');
  const buf = Buffer.alloc(ARCN1_HEADER_SIZE);
  ARCN1_MAGIC.copy(buf, 0);
  buf.writeUInt16BE(h.version, 8);
  buf[10] = h.algorithm;
  buf[11] = 0x00; // flags reserved
  h.iv.copy(buf, 12);
  h.tag.copy(buf, 24);
  return buf;
}

export function decodeHeader(buf: Buffer): ArcnHeader {
  if (buf.length < ARCN1_HEADER_SIZE) {
    throw new Error(`ARCN1 header requires at least 40 bytes, got ${buf.length}`);
  }
  if (!buf.subarray(0, 8).equals(ARCN1_MAGIC)) {
    throw new Error('bad magic bytes: input is not an ARCN1 stream');
  }
  const version = buf.readUInt16BE(8);
  if (version !== 1) {
    throw new Error(`unsupported format version: ${version}`);
  }
  const algorithm = buf[10]!;
  if (algorithm !== AlgorithmId.AES_256_GCM_64KB) {
    throw new Error(`unknown algorithm id: 0x${algorithm.toString(16)}`);
  }
  if (buf[11] !== 0) throw new Error('unsupported ARCN1 flags');
  const iv = buf.subarray(12, 24);
  const tag = buf.subarray(24, 40);
  return { version, algorithm, iv: Buffer.from(iv), tag: Buffer.from(tag) };
}

/**
 * AAD content covered by the header GCM tag: the first 24 bytes of the
 * header (magic + version + algorithm + flags + IV). The tag is the
 * last 16 bytes and is NOT included in its own AAD.
 */
export function headerAad(buf: Buffer): Buffer {
  return buf.subarray(0, 24);
}

export const ARCN1_CHUNK_HEADER_SIZE = 16; // u32 length + 12-byte IV
export const ARCN1_GCM_TAG_SIZE = 16;

export interface ChunkHeader {
  length: number;
  iv: Buffer;
}

export function encodeChunkHeader(h: ChunkHeader): Buffer {
  if (h.iv.length !== 12) throw new Error('iv must be 12 bytes');
  // Number.isInteger explicitly rejects NaN, Infinity, and non-integer
  // floats. Without it, Buffer.writeUInt32BE(NaN, 0) silently writes 0
  // — the same byte pattern as the trailer sentinel — and produces a
  // malformed stream the decoder would misread as end-of-stream.
  if (!Number.isInteger(h.length) || h.length < 0 || h.length > 0xffffffff) {
    throw new Error('length out of u32 range');
  }
  const buf = Buffer.alloc(ARCN1_CHUNK_HEADER_SIZE);
  buf.writeUInt32BE(h.length, 0);
  h.iv.copy(buf, 4);
  return buf;
}

export function decodeChunkHeader(buf: Buffer): ChunkHeader {
  if (buf.length < ARCN1_CHUNK_HEADER_SIZE) {
    throw new Error(`chunk header requires at least 16 bytes, got ${buf.length}`);
  }
  return {
    length: buf.readUInt32BE(0),
    iv: Buffer.from(buf.subarray(4, 16)),
  };
}

/**
 * The trailer starts with a 16-byte sentinel that is structurally
 * identical to a chunk header but with length=0. Encoders write
 * encodeTrailerSentinel(iv); decoders read 16 bytes and check
 * decodeTrailerSentinel to know whether to enter trailer-mode.
 */
export function encodeTrailerSentinel(iv: Buffer): Buffer {
  return encodeChunkHeader({ length: 0, iv });
}

export function decodeTrailerSentinel(buf: Buffer): boolean {
  if (buf.length < 16) return false;
  return buf.readUInt32BE(0) === 0;
}

/**
 * Trailer AAD: SHA-256(plaintext) (32 bytes) followed by chunk count (u64 BE).
 * 40 bytes total. The trailer GCM tag is computed over this AAD with no payload.
 */
export function trailerAad(plaintextSha256: Buffer, chunkCount: bigint): Buffer {
  if (plaintextSha256.length !== 32) throw new Error('plaintext sha256 must be 32 bytes');
  const buf = Buffer.alloc(40);
  plaintextSha256.copy(buf, 0);
  buf.writeBigUInt64BE(chunkCount, 32);
  return buf;
}
